import java.io.*;
import java.util.*;

public class Main {
    private static int compute(char[] s, char x) {
        for(int i = 0; i < s.length; i++) {
            if(s[i] == 'X') {
                s[i] = x;
            }
        }
        if(s[0] == '0') {
            return 0;
        }
        int total = 1;
        boolean firstX = true;
        for(int i = 0; i < s.length; i++) {
            if(s[i] == '_') {
                total *= (i == 0) ? 9 : 10;
            } else if(s[i] == 'X' && firstX) {
                total *= (i == 0) ? 9 : 10;
                firstX = false;
            }
        }
        return total;
    }
    private static boolean checkReplace(char[] s, char a, char b) {
        if(s[s.length-2] >= '0' && s[s.length-2] <= '9' && s[s.length-2] != a) {
            return false;
        }
        if(s[s.length-1] >= '0' && s[s.length-1] <= '9' && s[s.length-1] != b) {
            return false;
        }
        if(s[s.length-2] == 'X' && s[s.length-1] == 'X' && a != b) {
            return false;
        }
        return true;
    }
    public static void main(String[] args) throws java.io.IOException {
        java.io.BufferedReader br = new java.io.BufferedReader(new java.io.InputStreamReader(System.in));
        java.io.PrintWriter pw = new java.io.PrintWriter(new java.io.OutputStreamWriter(System.out));
