                t[t.length-1] = '0';
                if(s[s.length-2] == 'X') {
                    answer += compute(t, t[t.length-2]);
                } else if(s[s.length-1] == 'X') {
                    answer += compute(t, t[t.length-1]);
                } else {
                    answer += compute(t, 'X');
                }
            }
            if(checkReplace(s, '2', '5')) {
                char[] t = s.clone();
                t[t.length-2] = '2';
                t[t.length-1] = '5';
                if(s[s.length-2] == 'X') {
                    answer += compute(t, t[t.length-2]);
                } else if(s[s.length-1] == 'X') {
                    answer += compute(t, t[t.length-1]);
                } else {
                    answer += compute(t, 'X');
                }
            }
            if(checkReplace(s, '5', '0')) {
                char[] t = s.clone();
                t[t.length-2] = '5';
                t[t.length-1] = '0';
                if(s[s.length-2] == 'X') {
                    answer += compute(t, t[t.length-2]);
                } else if(s[s.length-1] == 'X') {
                    answer += compute(t, t[t.length-1]);
                } else {
                    answer += compute(t, 'X');
                }
            }
            if(checkReplace(s, '7', '5')) {
                char[] t = s.clone();
                t[t.length-2] = '7';
                t[t.length-1] = '5';
                if(s[s.length-2] == 'X') {
                    answer += compute(t, t[t.length-2]);
                } else if(s[s.length-1] == 'X') {
                    answer += compute(t, t[t.length-1]);
                } else {
                    answer += compute(t, 'X');
                }
            }
            pw.println(answer);
        }
        br.close();
        pw.close();
    }
}
